INSERT INTO skills (code, subject_code, name) VALUES
    ('PRIME_COMPOSITE', 'MATH', 'Prime and Composite Numbers'),
    ('TRANSITIONS_G5', 'ENGLISH', 'Transition Words');
INSERT INTO lessons (id, code, subject_code, grade_level, display_order, title, description) VALUES
    ('16000000-0000-0000-0000-000000000018', 'G5-PRIME-01', 'MATH', 'GRADE_5', 10, 'Prime and Composite Numbers', 'Tell numbers with exactly two factors from numbers with more.'),
    ('16000000-0000-0000-0000-000000000019', 'G5-ENG-TRANSITION-01', 'ENGLISH', 'GRADE_5', 9, 'Transition Words', 'Link ideas with words like however, therefore, and meanwhile.');
INSERT INTO exercises (id, lesson_code, skill_code, display_order, prompt, answer_index, explanation, hint) VALUES
    ('36000000-0000-0000-0000-000000000001', 'G5-FRACADDSUB-01', 'FRAC_ADDSUB', 4, 'What is 2/3 + 1/6?', 0, '2/3 = 4/6, so 4/6 + 1/6 = 5/6.', 'Rewrite 2/3 with a denominator of 6.'),
    ('36000000-0000-0000-0000-000000000002', 'G5-FRACADDSUB-01', 'FRAC_ADDSUB', 5, 'What is 7/8 - 3/8?', 1, '7/8 - 3/8 = 4/8, which simplifies to 1/2.', 'Subtract the tops, then simplify.'),
    ('36000000-0000-0000-0000-000000000003', 'G5-FRACADDSUB-01', 'FRAC_ADDSUB', 6, 'What is 1/3 + 1/2?', 2, '1/3 = 2/6 and 1/2 = 3/6, so 2/6 + 3/6 = 5/6.', 'Use 6 as the common denominator.'),
    ('36000000-0000-0000-0000-000000000004', 'G5-FRACMULT-01', 'FRAC_MULT', 4, 'What is 1/2 x 1/2?', 0, '1 x 1 = 1 and 2 x 2 = 4, so 1/4.', 'Half of a half.'),
    ('36000000-0000-0000-0000-000000000005', 'G5-FRACMULT-01', 'FRAC_MULT', 5, 'What is 3 x 1/4?', 1, '3 x 1/4 = 3/4. Three quarter-pieces make 3/4.', 'Write 3 as 3/1.'),
    ('36000000-0000-0000-0000-000000000006', 'G5-FRACMULT-01', 'FRAC_MULT', 6, 'What is 2/5 x 1/2?', 1, '2/5 x 1/2 = 2/10 = 1/5.', 'Multiply across, then simplify.'),
    ('36000000-0000-0000-0000-000000000007', 'G5-DECIMALOPS-01', 'DECIMAL_OPS', 4, 'What is 4.75 + 2.5?', 0, 'Line up the points: 4.75 + 2.50 = 7.25.', 'Write 2.5 as 2.50.'),
    ('36000000-0000-0000-0000-000000000008', 'G5-DECIMALOPS-01', 'DECIMAL_OPS', 5, 'What is 10 - 3.6?', 0, '10.0 - 3.6 = 6.4.', 'Write 10 as 10.0.'),
    ('36000000-0000-0000-0000-000000000009', 'G5-DECIMALOPS-01', 'DECIMAL_OPS', 6, 'What is 0.3 x 4?', 2, '3 x 4 = 12, with one decimal place: 1.2.', 'Count the decimal places.'),
    ('36000000-0000-0000-0000-000000000010', 'G5-VOLUME-01', 'VOLUME_G5', 4, 'A box is 5 cm long, 2 cm wide, and 3 cm tall. What is its volume?', 2, '5 x 2 x 3 = 30 cubic cm.', 'Multiply all three.'),
    ('36000000-0000-0000-0000-000000000011', 'G5-VOLUME-01', 'VOLUME_G5', 5, 'A cube has sides of 4 units. What is its volume?', 1, '4 x 4 x 4 = 64.', 'Side x side x side.'),
    ('36000000-0000-0000-0000-000000000012', 'G5-VOLUME-01', 'VOLUME_G5', 6, 'A box has a volume of 40 and a base area of 8. How tall is it?', 1, 'Volume = base area x height, so 40 / 8 = 5.', 'Divide the volume by the base area.'),
    ('36000000-0000-0000-0000-000000000013', 'G5-COORD-01', 'COORD_PLANE', 4, 'Start at the origin. Go 4 right and 2 up. What point are you at?', 1, 'Right gives x = 4, up gives y = 2: (4,2).', 'x comes first, then y.'),
    ('36000000-0000-0000-0000-000000000014', 'G5-COORD-01', 'COORD_PLANE', 5, 'What is the x-coordinate of the point (6,1)?', 1, 'The x-coordinate is the first number: 6.', 'x is first.'),
    ('36000000-0000-0000-0000-000000000015', 'G5-COORD-01', 'COORD_PLANE', 6, 'Which point is on the y-axis?', 0, 'Points on the y-axis have x = 0.', 'On the y-axis, you don''t go left or right.'),
    ('36000000-0000-0000-0000-000000000016', 'G5-ORDEROPS-01', 'ORDER_OPS', 4, 'What is 8 + 12 / 4?', 2, 'Divide first: 12 / 4 = 3, then 8 + 3 = 11.', 'Multiply and divide before adding.'),
    ('36000000-0000-0000-0000-000000000017', 'G5-ORDEROPS-01', 'ORDER_OPS', 5, 'What is (6 - 2) x 5?', 1, 'Parentheses first: 4, then 4 x 5 = 20.', 'Do the parentheses first.'),
    ('36000000-0000-0000-0000-000000000018', 'G5-ORDEROPS-01', 'ORDER_OPS', 6, 'What is 3 x 3 + 3?', 1, 'Multiply first: 9, then 9 + 3 = 12.', 'Multiply before adding.'),
    ('36000000-0000-0000-0000-000000000019', 'G5-PERCENT-01', 'PERCENT_INTRO', 4, 'What is 10% of 70?', 0, '10% is one tenth: 70 / 10 = 7.', '10% means divide by 10.'),
    ('36000000-0000-0000-0000-000000000020', 'G5-PERCENT-01', 'PERCENT_INTRO', 5, 'Which fraction equals 25%?', 0, '25% = 25/100 = 1/4.', 'Think of a quarter.'),
    ('36000000-0000-0000-0000-000000000021', 'G5-PERCENT-01', 'PERCENT_INTRO', 6, 'What is 50% of 36?', 1, '50% is half: 36 / 2 = 18.', '50% means half.'),
    ('36000000-0000-0000-0000-000000000022', 'G5-POWERS10-01', 'POWERS_10', 4, 'What is 4.5 x 10?', 1, 'Multiplying by 10 moves the decimal point one place right: 45.', 'Move the decimal point.'),
    ('36000000-0000-0000-0000-000000000023', 'G5-POWERS10-01', 'POWERS_10', 5, 'What is 300 / 100?', 1, '300 / 100 = 3.', 'Dividing by 100 moves the point two places left.'),
    ('36000000-0000-0000-0000-000000000024', 'G5-POWERS10-01', 'POWERS_10', 6, 'How many zeros are in 10 to the 4th power (10 x 10 x 10 x 10)?', 1, '10 x 10 x 10 x 10 = 10,000, which has 4 zeros.', 'Count the tens.'),
    ('36000000-0000-0000-0000-000000000025', 'G5-WORD-01', 'WORD_PROB_G5', 4, 'Pens cost $1.25 each. How much do 4 pens cost?', 0, '1.25 x 4 = 5.00.', 'Four quarters-and-a-dollar.'),
    ('36000000-0000-0000-0000-000000000026', 'G5-WORD-01', 'WORD_PROB_G5', 5, 'A 2.4-liter jug of juice is poured equally into 6 cups. How much is in each cup?', 2, '2.4 / 6 = 0.4 liters.', '24 / 6 = 4, then place the decimal.'),
    ('36000000-0000-0000-0000-000000000027', 'G5-WORD-01', 'WORD_PROB_G5', 6, 'Sam ran 1.5 km on Monday and twice as far on Tuesday. How far did he run in total?', 0, 'Tuesday: 1.5 x 2 = 3. Total: 1.5 + 3 = 4.5 km.', 'Find Tuesday first.'),
    ('36000000-0000-0000-0000-000000000028', 'G5-ENG-COMP-01', 'COMPREHENSION_G5', 4, 'Read: "The bakery''s line stretched around the block every morning before it even opened." What can you conclude?', 0, 'A long line shows many people want to buy there.', 'Why would people wait?'),
    ('36000000-0000-0000-0000-000000000029', 'G5-ENG-COMP-01', 'COMPREHENSION_G5', 5, 'Read: "Although Priya was exhausted, she finished her project before going to bed." What does this show about Priya?', 0, 'She kept working even though she was tired.', 'What does "although" signal?'),
    ('36000000-0000-0000-0000-000000000030', 'G5-ENG-COMP-01', 'COMPREHENSION_G5', 6, 'Read: "The river had risen overnight, covering the path the villagers used every day." What most likely caused this?', 1, 'Rivers rise quickly after heavy rain.', 'What makes rivers rise?'),
    ('36000000-0000-0000-0000-000000000031', 'G5-ENG-INFER-01', 'INFERENCE_G5', 4, 'Kai keeps checking the clock and tapping his foot outside the theater. What can you infer?', 0, 'Checking the clock and tapping show impatience.', 'What do these actions suggest?'),
    ('36000000-0000-0000-0000-000000000032', 'G5-ENG-INFER-01', 'INFERENCE_G5', 5, 'There are muddy paw prints across the kitchen floor. What can you infer?', 0, 'Paw prints mean an animal; mud means it was outside.', 'What makes paw prints?'),
    ('36000000-0000-0000-0000-000000000033', 'G5-ENG-INFER-01', 'INFERENCE_G5', 6, 'Lena smiled as she hung the blue ribbon on her wall. What can you infer?', 1, 'Blue ribbons are usually first-place prizes.', 'What is a blue ribbon for?'),
    ('36000000-0000-0000-0000-000000000034', 'G5-ENG-THEME-01', 'THEME_SUMMARY', 4, 'A story where two rivals work together to win has what theme?', 0, 'The rivals succeed by cooperating.', 'What lesson do they learn?'),
    ('36000000-0000-0000-0000-000000000035', 'G5-ENG-THEME-01', 'THEME_SUMMARY', 5, 'How is a theme different from a topic?', 2, 'Topic: friendship. Theme: true friends stand by you.', 'One is a word; one is a message.'),
    ('36000000-0000-0000-0000-000000000036', 'G5-ENG-THEME-01', 'THEME_SUMMARY', 6, 'A boy lies, gets caught, and loses his friends'' trust. What is the theme?', 0, 'The story shows the cost of lying.', 'What does the boy learn?'),
    ('36000000-0000-0000-0000-000000000037', 'G5-ENG-CLAUSE-01', 'CLAUSES_G5', 4, 'In "When the bell rang, students left," what is the independent clause?', 1, '"Students left" can stand alone as a sentence.', 'Which part makes sense by itself?'),
    ('36000000-0000-0000-0000-000000000038', 'G5-ENG-CLAUSE-01', 'CLAUSES_G5', 5, 'Which word starts a dependent clause?', 2, '"Although" makes a clause that can''t stand alone.', 'Subordinating words like although, because, when.'),
    ('36000000-0000-0000-0000-000000000039', 'G5-ENG-CLAUSE-01', 'CLAUSES_G5', 6, 'Which is a complete sentence?', 0, 'It has a subject and verb and stands alone.', 'Does it leave you waiting for more?'),
    ('36000000-0000-0000-0000-000000000040', 'G5-ENG-ROOT-01', 'ROOT_WORDS', 4, 'The root "graph" means "write." What does "autograph" mean?', 2, 'Auto (self) + graph (write) = writing your own name.', 'Auto means self.'),
    ('36000000-0000-0000-0000-000000000041', 'G5-ENG-ROOT-01', 'ROOT_WORDS', 5, 'The root "spect" means "look." Which word means a person who watches?', 0, 'A spectator looks at or watches an event.', 'Which person watches a game?'),
    ('36000000-0000-0000-0000-000000000042', 'G5-ENG-ROOT-01', 'ROOT_WORDS', 6, 'What is the root word in "uncomfortable"?', 1, 'Remove un- and -able to find comfort.', 'Take off the prefix and suffix.'),
    ('36000000-0000-0000-0000-000000000043', 'G5-ENG-PERSUADE-01', 'PERSUASIVE_INFORM', 4, '"Our town needs a new park because kids need safe places to play" is what type of text?', 1, 'It argues for a new park.', 'Is it trying to convince you?'),
    ('36000000-0000-0000-0000-000000000044', 'G5-ENG-PERSUADE-01', 'PERSUASIVE_INFORM', 5, 'Which is a common feature of persuasive writing?', 2, 'Persuasive writing gives reasons and asks you to act.', 'What helps convince someone?'),
    ('36000000-0000-0000-0000-000000000045', 'G5-ENG-PERSUADE-01', 'PERSUASIVE_INFORM', 6, '"Honeybees can visit 5,000 flowers in a day" is what type of text?', 1, 'It states a fact.', 'Is it giving an opinion?'),
    ('36000000-0000-0000-0000-000000000046', 'G5-ENG-POETRY-01', 'POETRY_BASICS', 4, 'What do we call the pattern of beats in a poem?', 1, 'Rhythm is the beat.', 'You can clap it.'),
    ('36000000-0000-0000-0000-000000000047', 'G5-ENG-POETRY-01', 'POETRY_BASICS', 5, 'A poem that is exactly 3 lines with 5, 7, and 5 syllables is a:', 2, 'A haiku has 5-7-5 syllables.', 'It comes from Japan.'),
    ('36000000-0000-0000-0000-000000000048', 'G5-ENG-POETRY-01', 'POETRY_BASICS', 6, '"Buzz," "pop," and "sizzle" are examples of:', 0, 'These words sound like what they mean.', 'Words that copy sounds.'),
    ('36000000-0000-0000-0000-000000000049', 'G5-ENG-POV-01', 'POINT_OF_VIEW', 4, 'A story that uses "you" to speak to the reader directly is in what point of view?', 1, '"You" is second person.', 'Who is being spoken to?'),
    ('36000000-0000-0000-0000-000000000050', 'G5-ENG-POV-01', 'POINT_OF_VIEW', 5, 'In third person omniscient, the narrator knows:', 0, 'Omniscient means all-knowing.', 'Omni means all.'),
    ('36000000-0000-0000-0000-000000000051', 'G5-ENG-POV-01', 'POINT_OF_VIEW', 6, '"I couldn''t believe my eyes when I opened the box." What point of view is this?', 1, '"I" and "my" show first person.', 'Look at the pronouns.'),
    ('36000000-0000-0000-0000-000000000052', 'G5-PRIME-01', 'PRIME_COMPOSITE', 1, 'Which number is prime?', 1, '7 has only two factors: 1 and 7.', 'Prime numbers have exactly two factors.'),
    ('36000000-0000-0000-0000-000000000053', 'G5-PRIME-01', 'PRIME_COMPOSITE', 2, 'Which number is composite?', 2, '12 has factors 1, 2, 3, 4, 6, 12, so it''s composite.', 'Composite numbers have more than two factors.'),
    ('36000000-0000-0000-0000-000000000054', 'G5-PRIME-01', 'PRIME_COMPOSITE', 3, 'Is 2 prime or composite?', 1, '2 has factors 1 and 2 only. It is the only even prime.', 'List its factors.'),
    ('36000000-0000-0000-0000-000000000055', 'G5-PRIME-01', 'PRIME_COMPOSITE', 4, 'Is 1 prime or composite?', 1, '1 has only one factor, so it is neither prime nor composite.', 'Count its factors.'),
    ('36000000-0000-0000-0000-000000000056', 'G5-PRIME-01', 'PRIME_COMPOSITE', 5, 'Which list shows only prime numbers?', 0, '1 isn''t prime and 9 = 3 x 3.', 'Check each number for factors.'),
    ('36000000-0000-0000-0000-000000000057', 'G5-PRIME-01', 'PRIME_COMPOSITE', 6, 'What is the prime factorization of 12?', 1, '12 = 2 x 2 x 3, using only primes.', 'Keep breaking factors down until all are prime.'),
    ('36000000-0000-0000-0000-000000000058', 'G5-ENG-TRANSITION-01', 'TRANSITIONS_G5', 1, 'Which transition shows contrast?', 2, '"However" introduces an opposite idea.', 'Which word means "but"?'),
    ('36000000-0000-0000-0000-000000000059', 'G5-ENG-TRANSITION-01', 'TRANSITIONS_G5', 2, 'Which transition shows a result?', 0, '"Therefore" shows something happened as a result.', 'Which word means "so"?'),
    ('36000000-0000-0000-0000-000000000060', 'G5-ENG-TRANSITION-01', 'TRANSITIONS_G5', 3, 'Which word fits? "It was raining. ___, the game was cancelled."', 1, 'The rain caused the cancellation.', 'Is it a cause and effect?'),
    ('36000000-0000-0000-0000-000000000061', 'G5-ENG-TRANSITION-01', 'TRANSITIONS_G5', 4, 'Which transition shows time order?', 2, '"Afterward" tells when.', 'Which word is about time?'),
    ('36000000-0000-0000-0000-000000000062', 'G5-ENG-TRANSITION-01', 'TRANSITIONS_G5', 5, 'Which transition introduces an example?', 1, '"For instance" gives an example.', 'Which phrase means "for example"?'),
    ('36000000-0000-0000-0000-000000000063', 'G5-ENG-TRANSITION-01', 'TRANSITIONS_G5', 6, 'Which word fits? "Cats are independent. Dogs, ___, love attention."', 1, 'It contrasts cats and dogs.', 'Is it comparing differences?');
